            new XgLibraryEntry { id="qianziwen", title="千字文", titleEn="Thousand Character Classic", author="周兴嗣", authorEn="Zhou Xingsi", language="zh", publication="六世纪梁代成书", sourceUrl="https://zh.wikipedia.org/wiki/%E5%8D%83%E5%AD%97%E6%96%87", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="short", introZh="这篇蒙学韵文以一千个不重复的字组织天地、历史和日常知识，方便初学者诵记。", introEn="This primer arranges a thousand different characters into a rhythmic survey of nature, history and daily life.", insightZh="整齐的节奏帮助记忆，但记住字序不等于理解每一条知识。", insightEn="Rhythm supports memory; remembering the sequence does not establish understanding.", questionZh="会背字序，就一定懂意思吗？", questionEn="Does reciting the sequence prove understanding?", keysZh="不等于;理解;不一定", keysEn="not;understand;meaning", availableBy=19000101, stage=2, price=80 },
            new XgLibraryEntry { id="dizigui", title="弟子规", titleEn="Standards for Being a Good Pupil and Child", author="李毓秀", authorEn="Li Yuxiu", language="zh", publication="清代康熙年间成书", sourceUrl="https://zh.wikipedia.org/wiki/%E5%BC%9F%E5%AD%90%E8%A7%84", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="short", introZh="这部启蒙读物把家庭礼节、待人方式和读书习惯写成便于记诵的短句。", introEn="This primer presents family etiquette, conduct and study habits in short rhythmic lines.", insightZh="它反映传统家庭秩序。阅读时可以区分尊重他人与无条件服从。", insightEn="It reflects a traditional family order. Respect for others can be distinguished from unconditional obedience.", questionZh="尊重别人和无条件服从是一回事吗？", questionEn="Are respect and unconditional obedience the same?", keysZh="不是;区分;不一样", keysEn="different;not;distinguish", availableBy=19000101, stage=2, price=60 },
            new XgLibraryEntry { id="baijiaxing", title="百家姓", titleEn="Hundred Family Surnames", author="佚名", authorEn="Anonymous", language="zh", publication="北宋初形成", sourceUrl="https://zh.wikipedia.org/wiki/%E7%99%BE%E5%AE%B6%E5%A7%93", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="short", introZh="这篇蒙学材料把许多姓氏串成韵文。排列顺序带有编纂时代的社会背景。", introEn="This primer turns family names into a mnemonic verse whose order reflects its historical setting.", insightZh="姓氏排列不是人口统计，排在前面并不表示人数最多。", insightEn="The ordering is not a population census; first position does not mean the largest population.", questionZh="排在前面的姓一定人最多吗？", questionEn="Must the first surname have the most people?", keysZh="不是;不一定;统计", keysEn="not;census;population", availableBy=19000101, stage=2, price=50 },
            new XgLibraryEntry { id="shijing", title="诗经", titleEn="Classic of Poetry", author="佚名诗人；历代编纂", authorEn="Anonymous poets and compilers", language="zh", publication="诗歌约作于公元前十一至七世纪", sourceUrl="https://zh.wikipedia.org/wiki/%E8%AF%97%E7%BB%8F", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这部早期诗歌总集收录爱情、劳动、祭祀和政治生活，使不同社会声音并列出现。", introEn="This early poetry collection places love, work, ritual and political life alongside one another.", insightZh="反复出现的句式既形成歌唱节奏，也让情绪在细小变化中推进。", insightEn="Repeated forms create musical rhythm while small changes develop the emotion.", questionZh="重复的句子除了好记，还有什么作用？", questionEn="What can repeated lines do beyond aiding memory?", keysZh="节奏;情绪;变化", keysEn="rhythm;emotion;variation", availableBy=19000101, stage=3, price=350 },
            new XgLibraryEntry { id="chuci", title="楚辞", titleEn="Songs of Chu", author="屈原、宋玉等；王逸章句传世", authorEn="Qu Yuan, Song Yu and others", language="zh", publication="战国至汉代作品汇编", sourceUrl="https://zh.wikipedia.org/wiki/%E6%A5%9A%E8%BE%9E", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这些作品把强烈的个人声音、神话想象与楚地文化交织起来，形成与四言诗不同的表达。", introEn="These works combine an intense personal voice, mythic imagination and the culture of Chu.", insightZh="远游和香草不只描写景物，也承载理想、失意与自我坚持。", insightEn="Journeys and fragrant plants carry ideals, disappointment and persistence as well as describing scenery.", questionZh="远游与香草只是景物吗？", questionEn="Are journeys and fragrant plants merely scenery?", keysZh="理想;象征;坚持", keysEn="ideal;symbol;persistence", availableBy=19000101, stage=4, price=500 },
            new XgLibraryEntry { id="daodejing", title="道德经", titleEn="Dao De Jing", author="老子（传统归属）", authorEn="Traditionally attributed to Laozi", language="zh", publication="战国时期文本逐步形成", sourceUrl="https://zh.wikipedia.org/wiki/%E9%81%93%E5%BE%B7%E7%BB%8F", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这部短篇哲学文本反复讨论强弱、有无和行动的限度，常用看似相反的说法推动思考。", introEn="This compact philosophical text explores strength, absence and the limits of action through apparent opposites.", insightZh="无为可以理解为减少强行干预，不能简单等同于什么都不做。", insightEn="Non-action can suggest reducing coercive interference, rather than doing absolutely nothing.", questionZh="无为为什么不必等于完全不行动？", questionEn="Why need non-action not mean total inactivity?", keysZh="干预;强行;顺应", keysEn="interference;coercion;forcing", availableBy=19000101, stage=3, price=250 },
            new XgLibraryEntry { id="zhuangzi", title="庄子", titleEn="Zhuangzi", author="庄周及后学", authorEn="Zhuang Zhou and later writers", language="zh", publication="战国至汉初形成", sourceUrl="https://zh.wikipedia.org/wiki/%E5%BA%84%E5%AD%90", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="寓言、对话与奇异形象不断改变观察问题的角度，松动人对固定标准的信心。", introEn="Fables, dialogues and strange images repeatedly change the viewpoint from which a problem is observed.", insightZh="同一事物从不同位置看会有不同价值，判断需要意识到自身立场。", insightEn="An object's value can change with perspective; judgment should recognize its own standpoint.", questionZh="换个观察位置，判断为什么可能改变？", questionEn="Why might a changed viewpoint alter a judgment?", keysZh="立场;角度;价值", keysEn="perspective;standpoint;value", availableBy=19000101, stage=4, price=450 },
            new XgLibraryEntry { id="mengzi", title="孟子", titleEn="Mencius", author="孟子及弟子", authorEn="Mencius and his disciples", language="zh", publication="战国时期成书", sourceUrl="https://zh.wikipedia.org/wiki/%E5%AD%9F%E5%AD%90", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="书中以对话论辩人性、政治和道德修养，把个人的恻隐之心联系到公共责任。", introEn="Its dialogues connect moral cultivation and compassion with political responsibility.", insightZh="同情需要落实为照顾他人的制度与行动，不能只停留在一瞬间的感动。", insightEn="Compassion needs institutions and actions that care for others, not merely a passing feeling.", questionZh="有同情心之后，还需要什么？", questionEn="What is needed beyond a feeling of compassion?", keysZh="行动;制度;照顾", keysEn="action;institution;care", availableBy=19000101, stage=3, price=350 },
            new XgLibraryEntry { id="xunzi", title="荀子", titleEn="Xunzi", author="荀况及后学", authorEn="Xun Kuang and later followers", language="zh", publication="战国末期形成", sourceUrl="https://zh.wikipedia.org/wiki/%E8%8D%80%E5%AD%90", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这部思想著作强调学习、礼制和长期实践在塑造人的行为方面的作用。", introEn="These philosophical writings emphasize learning, ritual and sustained practice in shaping conduct.", insightZh="能力和品行需要累积训练；承认天性局限不等于否认改变的可能。", insightEn="Skill and character require accumulated practice; limits in natural tendencies do not rule out change.", questionZh="天性有局限，为什么仍然可以进步？", questionEn="Why can people improve despite natural limitations?", keysZh="学习;实践;训练", keysEn="learning;practice;training", availableBy=19000101, stage=4, price=450 },
            new XgLibraryEntry { id="mozi", title="墨子", titleEn="Mozi", author="墨翟及墨家后学", authorEn="Mo Di and the Mohist school", language="zh", publication="战国时期汇编", sourceUrl="https://zh.wikipedia.org/wiki/%E5%A2%A8%E5%AD%90", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="墨家讨论兼爱、反对攻伐、节用与论证，常追问一种主张能给人带来什么实际结果。", introEn="Mohist writings discuss inclusive care, opposition to aggression, thrift and the practical consequences of claims.", insightZh="评价政策不能只听漂亮言辞，还要检验它是否减少伤害、改善生活。", insightEn="Policy should be assessed through harm and welfare, not attractive language alone.", questionZh="判断政策好坏，除了听说法还看什么？", questionEn="What should assess a policy beyond its rhetoric?", keysZh="结果;伤害;生活", keysEn="consequence;harm;welfare", availableBy=19000101, stage=4, price=450 },
            new XgLibraryEntry { id="hanfeizi", title="韩非子", titleEn="Han Feizi", author="韩非等", authorEn="Han Fei and other writers", language="zh", publication="战国末期形成", sourceUrl="https://zh.wikipedia.org/wiki/%E9%9F%A9%E9%9D%9E%E5%AD%90", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这些政治论述研究制度、权力和奖惩，表现出对仅靠个人德行治理的怀疑。", introEn="These political essays examine institutions, power and incentives, questioning reliance on personal virtue alone.", insightZh="稳定规则可能约束任意性，但严厉控制也会产生代价，需要同时考察。", insightEn="Stable rules can constrain arbitrariness, but coercive control also carries costs.", questionZh="规则稳定，就代表控制没有代价吗？", questionEn="Do stable rules make coercive control cost-free?", keysZh="代价;不是;约束", keysEn="cost;not;coercion", availableBy=19000101, stage=5, price=500 },
            new XgLibraryEntry { id="sunzi", title="孙子兵法", titleEn="The Art of War", author="孙武（传统归属）", authorEn="Traditionally attributed to Sun Wu", language="zh", publication="先秦军事著作", sourceUrl="https://zh.wikipedia.org/wiki/%E5%AD%99%E5%AD%90%E5%85%B5%E6%B3%95", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这部兵书把战争看作需要计算成本、情报与条件的危险行动，而非单纯比拼勇气。", introEn="This military treatise treats war as a dangerous undertaking involving costs, information and circumstances.", insightZh="谋划的价值之一是减少不必要的交战，胜利也要衡量所付代价。", insightEn="Planning can avoid unnecessary fighting, and victory must be weighed against its cost.", questionZh="为什么不能只用打赢来评价一场行动？", questionEn="Why is winning alone an incomplete measure of an operation?", keysZh="代价;成本;损失", keysEn="cost;loss;harm", availableBy=19000101, stage=3, price=250 },
            new XgLibraryEntry { id="shiji", title="史记", titleEn="Records of the Grand Historian", author="司马迁", authorEn="Sima Qian", language="zh", publication="约公元前一世纪成书", sourceUrl="https://zh.wikipedia.org/wiki/%E5%8F%B2%E8%AE%B0", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="advanced", introZh="纪传体结构把帝王、制度与不同人物的生命故事放进同一历史视野。", introEn="Its biographical structure brings rulers, institutions and varied individual lives into a shared historical view.", insightZh="人物处境与选择相互作用，理解历史不能只把结果归给个人性格。", insightEn="Circumstances interact with choices; historical outcomes cannot all be assigned to personality.", questionZh="理解人物命运，为什么还要看时代处境？", questionEn="Why consider historical circumstances when interpreting a life?", keysZh="处境;时代;选择", keysEn="circumstance;context;choice", availableBy=19000101, stage=5, price=1500 },
            new XgLibraryEntry { id="zizhitongjian", title="资治通鉴", titleEn="Comprehensive Mirror for Aid in Government", author="司马光等", authorEn="Sima Guang and collaborators", language="zh", publication="1084年完成", sourceUrl="https://zh.wikipedia.org/wiki/%E8%B5%84%E6%B2%BB%E9%80%9A%E9%89%B4", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="advanced", introZh="这部编年史按时间组织漫长的政治变化，关注决策如何连成后果。", introEn="This chronological history traces political change and the chains of consequences that follow decisions.", insightZh="前后相继不自动等于因果，需要比较当事人的条件和可选方案。", insightEn="Sequence alone does not prove causation; circumstances and available alternatives matter.", questionZh="事情先后发生，就一定是因果吗？", questionEn="Does happening in sequence establish causation?", keysZh="不一定;条件;因果", keysEn="not;condition;causation", availableBy=19000101, stage=5, price=1500 },
            new XgLibraryEntry { id="shanhaijing", title="山海经", titleEn="Classic of Mountains and Seas", author="佚名", authorEn="Anonymous", language="zh", publication="战国至汉代逐步形成", sourceUrl="https://zh.wikipedia.org/wiki/%E5%B1%B1%E6%B5%B7%E7%BB%8F", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="山川、族群、物产和奇异生灵共同组成一个带有神话色彩的地理世界。", introEn="Mountains, peoples, resources and strange beings form a geography shaped by myth.", insightZh="它保存古人的想象与知识分类，不宜直接当作现代自然科学记录。", insightEn="It preserves historical imagination and classification, rather than functioning as modern natural science.", questionZh="为什么不能把所有奇兽都当作科学记录？", questionEn="Why not treat every strange creature as a scientific observation?", keysZh="神话;想象;分类", keysEn="myth;imagination;classification", availableBy=19000101, stage=3, price=300 },
            new XgLibraryEntry { id="soushenji", title="搜神记", titleEn="In Search of the Supernatural", author="干宝", authorEn="Gan Bao", language="zh", publication="四世纪成书，传本经后世辑整", sourceUrl="https://zh.wikipedia.org/wiki/%E6%90%9C%E7%A5%9E%E8%AE%B0", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="志怪故事记录人与神灵、鬼魅及异事相遇，展示古人怎样解释异常经验。", introEn="Accounts of spirits and strange events show how people explained experiences outside the ordinary.", insightZh="故事的历史价值包括当时的信念与恐惧，不必以证明异事真实为前提。", insightEn="Their historical value includes beliefs and fears; it does not depend on proving supernatural events.", questionZh="不证明鬼神存在，这些故事仍有什么价值？", questionEn="What value remains without proving spirits exist?", keysZh="信念;恐惧;文化", keysEn="belief;fear;culture", availableBy=19000101, stage=3, price=300 },
            new XgLibraryEntry { id="shishuoxinyu", title="世说新语", titleEn="A New Account of Tales of the World", author="刘义庆及门下文士", authorEn="Liu Yiqing and his circle", language="zh", publication="五世纪编纂", sourceUrl="https://zh.wikipedia.org/wiki/%E4%B8%96%E8%AF%B4%E6%96%B0%E8%AF%AD", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="短小逸事描绘魏晋人物的言谈、风度与评价，常把一个性格瞬间压缩在几句话中。", introEn="Brief anecdotes capture speech, style and judgments of Wei-Jin figures in concentrated moments.", insightZh="逸事经过选择和塑造，能呈现文化理想，却不等于人物的完整档案。", insightEn="Selected anecdotes reveal cultural ideals but are not complete biographies.", questionZh="一个漂亮逸事能代表一个人的全部吗？", questionEn="Can one striking anecdote represent an entire person?", keysZh="不能;选择;不完整", keysEn="not;selected;incomplete", availableBy=19000101, stage=3, price=300 },
