            new XgLibraryEntry { id="gushishijiu", title="古诗十九首", titleEn="Nineteen Old Poems", author="佚名", authorEn="Anonymous", language="zh", publication="汉代作品；六世纪文选收录", sourceUrl="https://zh.wikipedia.org/wiki/%E5%8F%A4%E8%AF%97%E5%8D%81%E4%B9%9D%E9%A6%96", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="short", introZh="这些匿名诗歌反复写离别、时光与人生短促，把抽象感慨放进旅途和庭院。", introEn="These anonymous poems place separation, passing time and mortality in journeys and domestic scenes.", insightZh="熟悉的物象能够承载复杂感情，情绪并不需要直接解释完毕。", insightEn="Familiar images can carry complex feeling without spelling out every emotion.", questionZh="诗里写庭院和道路，为什么也能写离愁？", questionEn="How can courtyards and roads express separation?", keysZh="物象;感情;承载", keysEn="image;feeling;carry", availableBy=19000101, stage=2, price=100 },
