            new XgLibraryEntry { id="sishenyongsheng", title="三体Ⅲ：死神永生", titleEn="Death's End", author="刘慈欣", authorEn="Liu Cixin", language="zh", publication="2010年出版", sourceUrl="https://zh.wikipedia.org/wiki/%E4%B8%89%E4%BD%93III%EF%BC%9A%E6%AD%BB%E7%A5%9E%E6%B0%B8%E7%94%9F", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="advanced", introZh="故事把时间与空间尺度不断放大，安全、爱和文明延续的选择失去简单答案。", introEn="Expanding scales of time and space complicate choices about safety, affection and civilizational continuity.", insightZh="局部善意与宏观后果可能发生冲突，判断需要说明所采用的尺度。", insightEn="Local good intentions can conflict with large-scale consequences; judgment should state its scale.", questionZh="为什么同一选择在不同尺度下评价会变？", questionEn="Why can a choice be judged differently at different scales?", keysZh="后果;尺度;冲突", keysEn="consequence;scale;conflict", availableBy=20110101, stage=5, price=1000 },
            new XgLibraryEntry { id="jieyou", title="解忧杂货店", titleEn="The Miracles of the Namiya General Store", author="东野圭吾", authorEn="Keigo Higashino", language="zh", publication="日文2012年；简体中文版2014年", sourceUrl="https://zh.wikipedia.org/wiki/%E8%A7%A3%E5%BF%A7%E6%9D%82%E8%B4%A7%E5%BA%97", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="跨越时间的来信与回信把陌生人的难题连在一起，建议改变关系，也带来责任。", introEn="Letters crossing time connect strangers' dilemmas as advice changes relationships and creates responsibility.", insightZh="帮助不是替别人拥有全部答案，而是认真理解对方正在面对的选择。", insightEn="Helping is not possessing every answer for someone else; it begins with understanding their choices.", questionZh="替别人解忧是否就是替他们决定一切？", questionEn="Does helping someone mean deciding everything for them?", keysZh="理解;选择;不是", keysEn="understand;choice;not", availableBy=20150101, stage=3, price=400 },
            new XgLibraryEntry { id="congni", title="从你的全世界路过", titleEn="I Belonged to You", author="张嘉佳", authorEn="Zhang Jiajia", language="zh", publication="2013年出版", sourceUrl="https://zh.wikipedia.org/wiki/%E4%BB%8E%E4%BD%A0%E7%9A%84%E5%85%A8%E4%B8%96%E7%95%8C%E8%B7%AF%E8%BF%87", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="short", introZh="短篇故事围绕相遇、离别与城市生活展开，以近距离的口语感连接读者的情绪经验。", introEn="Short stories about encounters, partings and urban life use an intimate conversational voice.", insightZh="相似情绪能够引起共鸣，但别人的故事不能直接替代自己的生活判断。", insightEn="Shared emotions invite recognition without making another person's story a substitute for personal judgment.", questionZh="有共鸣的故事一定适合照着生活吗？", questionEn="Should a relatable story become a blueprint for one's life?", keysZh="判断;不同;不一定", keysEn="judgment;different;not", availableBy=20140101, stage=2, price=150 },
            new XgLibraryEntry { id="alice", title="爱丽丝漫游奇境记", titleEn="Alice's Adventures in Wonderland", author="刘易斯·卡罗尔", authorEn="Lewis Carroll", language="en", publication="1865年英文初版", sourceUrl="https://en.wikipedia.org/wiki/Alice%27s_Adventures_in_Wonderland", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="short", introZh="爱丽丝在奇境中面对不断变化的规则、语言和身份，熟悉的常识失去稳定地位。", introEn="Alice encounters unstable rules, language and identity in a world where familiar common sense no longer holds.", insightZh="荒诞对话让语言的歧义变得可见，也提醒人不要把权威口吻当作逻辑。", insightEn="Absurd exchanges expose ambiguity and show that an authoritative tone is not the same as sound reasoning.", questionZh="说话很有权威，为什么仍可能不合逻辑？", questionEn="Why can an authoritative statement still be illogical?", keysZh="逻辑;歧义;规则", keysEn="reasoning;ambiguity;rule", availableBy=19000101, stage=2, price=150 },
            new XgLibraryEntry { id="lookingglass", title="爱丽丝镜中奇遇记", titleEn="Through the Looking-Glass", author="刘易斯·卡罗尔", authorEn="Lewis Carroll", language="en", publication="1871年英文初版，题签1872年", sourceUrl="https://en.wikipedia.org/wiki/Through_the_Looking-Glass", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="镜中世界像棋局一样安排移动，方向、时间与词义经常反转。", introEn="The looking-glass world arranges movement like a chess game while reversing direction, time and meanings.", insightZh="规则可以使故事有结构，也可以在被滥用时让参与者困惑。", insightEn="Rules can structure an experience while confusing participants when applied perversely.", questionZh="有规则的世界为什么也可能令人困惑？", questionEn="Why can a rule-governed world still be confusing?", keysZh="反转;滥用;解释", keysEn="reversal;misuse;interpretation", availableBy=19000101, stage=3, price=250 },
            new XgLibraryEntry { id="littlewomen", title="小妇人", titleEn="Little Women", author="路易莎·梅·奥尔科特", authorEn="Louisa May Alcott", language="en", publication="1868至1869年英文两部", sourceUrl="https://en.wikipedia.org/wiki/Little_Women", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="四姐妹在家庭生活、写作、工作与亲密关系中成长，各自愿望并不相同。", introEn="Four sisters grow through family life, writing, work and relationships while pursuing different aspirations.", insightZh="成长不必只有一种成功模样；照顾关系与保持个人愿望需要协商。", insightEn="Growing up need not follow one model of success; care and personal aspirations require negotiation.", questionZh="四姐妹为什么不必追求同一种成功？", questionEn="Why need the four sisters not share one definition of success?", keysZh="不同;愿望;个人", keysEn="different;aspiration;individual", availableBy=19000101, stage=3, price=500 },
