            new XgLibraryEntry { id="treasureisland", title="金银岛", titleEn="Treasure Island", author="罗伯特·路易斯·史蒂文森", authorEn="Robert Louis Stevenson", language="en", publication="1881至1882年连载；1883年英文单行本", sourceUrl="https://en.wikipedia.org/wiki/Treasure_Island", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="吉姆的寻宝航程充满背叛与临时同盟，危险让他不断重新判断成年人。", introEn="Jim's treasure voyage brings betrayals and shifting alliances that force him to reassess adults.", insightZh="魅力与可信度不能直接等同，人物需要通过具体行为而非气势来判断。", insightEn="Charm is not the same as trustworthiness; actions matter more than impressive appearances.", questionZh="一个人很有魅力，就一定可信吗？", questionEn="Does charisma guarantee trustworthiness?", keysZh="行为;不一定;判断", keysEn="action;not;judgment", availableBy=19000101, stage=3, price=300 },
            new XgLibraryEntry { id="prideprejudice", title="傲慢与偏见", titleEn="Pride and Prejudice", author="简·奥斯汀", authorEn="Jane Austen", language="en", publication="1813年英文初版", sourceUrl="https://en.wikipedia.org/wiki/Pride_and_Prejudice", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="伊丽莎白与达西在阶层期待和第一印象中误判彼此，关系随着新信息而改变。", introEn="Elizabeth and Darcy misjudge each other amid class expectations and first impressions, then encounter new information.", insightZh="修正判断需要承认自己的偏见，而不只是等待别人证明自己错了。", insightEn="Revising a judgment requires acknowledging one's own bias, not merely demanding that others change.", questionZh="获得新信息后，为什么还需要反省自己？", questionEn="Why is self-reflection needed after receiving new information?", keysZh="偏见;判断;承认", keysEn="bias;judgment;acknowledge", availableBy=19000101, stage=4, price=500 },
            new XgLibraryEntry { id="frankenstein", title="弗兰肯斯坦", titleEn="Frankenstein", author="玛丽·雪莱", authorEn="Mary Shelley", language="en", publication="1818年英文初版", sourceUrl="https://en.wikipedia.org/wiki/Frankenstein", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="advanced", introZh="创造者造出生命后逃避面对它，受造者的孤独与愤怒把创造行为变成责任问题。", introEn="A creator withdraws from the life he has made, while the creature's isolation turns creation into a question of responsibility.", insightZh="能造出某种东西，不代表已经解决如何照顾它、回应后果的问题。", insightEn="The ability to create something does not settle how to care for it or answer for its consequences.", questionZh="创造成功以后，责任就结束了吗？", questionEn="Does responsibility end when creation succeeds?", keysZh="照顾;后果;没有", keysEn="care;consequence;not", availableBy=19000101, stage=5, price=800 },
            new XgLibraryEntry { id="sherlock", title="福尔摩斯历险记", titleEn="The Adventures of Sherlock Holmes", author="阿瑟·柯南·道尔", authorEn="Arthur Conan Doyle", language="en", publication="1892年英文结集出版", sourceUrl="https://en.wikipedia.org/wiki/The_Adventures_of_Sherlock_Holmes", materialKind="original-guide", rights="Original game guide; no original book text, modern translation, notes, illustrations or cover reproduced.", band="classic", introZh="这些侦探短篇通过观察、误导与解释重组线索，让普通细节获得新的意义。", introEn="These detective stories reorganize clues through observation, misdirection and explanation, changing the meaning of ordinary details.", insightZh="观察必须连接到可检验的推理，细节多并不自动意味着结论可靠。", insightEn="Observation needs testable reasoning; collecting many details does not guarantee a reliable conclusion.", questionZh="注意到很多细节，就一定推理正确吗？", questionEn="Does noticing many details guarantee correct reasoning?", keysZh="检验;推理;不一定", keysEn="test;reason;not", availableBy=19000101, stage=3, price=400 },
